  if (typeof name !== 'string') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Name field must be a string'
    });
  }

  res.status(201).json({
    id: Date.now(),
    name: name,
    email: `${name.toLowerCase().replace(/\s+/g, '.')}@example.com`
  });
});

